    #[test]
    fn complete_original_manifests_match_independent_rust_digest() {
        let packets = vec![
            packet_0(),
            packet_1(),
            packet_2(),
            packet_3(),
            packet_4(),
            packet_5(),
            packet_6(),
            packet_7(),
            packet_8(),
            packet_9(),
            packet_10(),
            packet_11(),
            packet_12(),
            packet_13(),
            packet_14(),
            packet_15(),
            packet_16(),
            packet_17(),
            packet_18(),
        ];
        assert_eq!(packets.len(), super::RULES.len());
        for (rule, mut manifest) in super::RULES.iter().zip(packets) {
            let digest = crate::owned_command::cubin::attention_policy::digest(&manifest);
            assert_eq!(digest, rule.abi);
            super::super::require_cohort_rule(true, rule.image, digest).unwrap();
            manifest.grid[0] += 1;
            let changed = crate::owned_command::cubin::attention_policy::digest(&manifest);
            assert!(super::super::require_cohort_rule(true, rule.image, changed).is_err());
        }
    }
